package io.github.miklires.mcodes;import java.time.Instant;import java.util.*;public record CodeDefinition(String code,CodeType type,UUID owner,int maxUses,int perPlayer,Instant expiresAt,List<String>redeemerCommands,List<String>ownerCommands){public CodeDefinition{code=normalize(code);if(code.length()<3||code.length()>32)throw new IllegalArgumentException("Code length must be 3..32");if(maxUses<0||perPlayer<1)throw new IllegalArgumentException("Invalid limits");redeemerCommands=List.copyOf(redeemerCommands);ownerCommands=List.copyOf(ownerCommands);}public static String normalize(String value){return value.trim().toUpperCase(Locale.ROOT);}}
